"""Original solid-tumor questions: hepatobiliary, stromal, genitourinary and melanoma."""
from create_oncology_breast_gi import rows,q,LU,SL,BR,MO,CR,GA,PA,ref
HC=ref('AASLD hepatocellular carcinoma practice guidance','https://pmc.ncbi.nlm.nih.gov/articles/PMC10663390/')
GS=ref('NCI GIST professional summary','https://www.cancer.gov/types/soft-tissue-sarcoma/hp/gist-treatment-pdq')
TE=ref('NCI testicular cancer professional summary','https://www.cancer.gov/types/testicular/hp/testicular-treatment-pdq')
ME=ref('NCI melanoma professional summary','https://www.cancer.gov/types/skin/hp/melanoma-treatment-pdq')

q('In an appropriate high-risk cirrhotic patient, a liver lesion meets validated characteristic multiphasic imaging criteria for HCC. Which principle is correct?', 'A noninvasive imaging diagnosis can be appropriate without routine biopsy when the validated criteria and population apply',[
 ('Every liver lesion in every patient can be called HCC from arterial enhancement alone','Population, size and the complete imaging pattern matter.'),('AFP elevation is mandatory despite characteristic imaging','AFP is not required in every HCC case.'),('Imaging can never establish HCC without tissue in any circumstance','Validated high-risk pathways permit noninvasive diagnosis.')],
 'An exception to routine tissue diagnosis has a defined scope','**HCC imaging criteria depend on the at-risk population and lesion characteristics.**',['Indeterminate or atypical findings require further assessment.','The same rule should not be applied to an unrelated low-risk patient.'],'**Assess tumor extent and liver reserve for treatment planning.**',['Use multidisciplinary review of uncertain lesions.','Do not infer histology from an incomplete scan phase.'],[['Population','Appropriate high-risk context'],['Imaging','Complete validated pattern'],['Atypical lesion','Further assessment/selected biopsy']],[HC])

q('A gastric mesenchymal tumor has compatible morphology with KIT and DOG1 expression. Which diagnosis is most strongly supported?', 'Gastrointestinal stromal tumor',[
 ('Gastric adenocarcinoma','This is an epithelial tumor with a different usual marker pattern.'),('MALT lymphoma','This is a lymphoid process.'),('A smooth-muscle tumor established by location alone','Morphology and the KIT/DOG1 pattern favor GIST, though a panel is required.')],
 'Lineage classification changes treatment','**GIST has characteristic stromal biology and frequent KIT/PDGFRA pathway alterations.**',['Not every case has the same marker or mutation profile.','Mutation subtype can affect targeted-drug sensitivity.'],'**Obtain appropriate molecular characterization when treatment decisions require it.**',['Risk assessment includes site, size, mitoses and rupture context.','Do not choose therapy from KIT staining alone.'],[['Lineage','Stromal'],['Markers','KIT/DOG1 supportive'],['Molecular result','Treatment-relevant']],[GS],style='clinical_scenario')

q('A renal mass is found incidentally without the classic hematuria–pain–mass triad. Which statement is correct?', 'Renal cell carcinoma remains possible; absence of the classic triad does not exclude it',[
 ('The triad is required for diagnosis','Many RCCs are discovered incidentally.'),('Every incidental renal lesion is malignant','Cysts and benign tumors are also possible.'),('A normal urinalysis makes solid-mass imaging unnecessary','Imaging characterization remains important.')],
 'Classic advanced presentations are not required','**A renal lesion needs anatomical characterization rather than a symptom checklist alone.**',['Enhancement, cystic features and other imaging findings guide assessment.','Renal function and patient factors influence the strategy.'],'**Use a renal-mass pathway with appropriate specialist review.**',['Biopsy is selected according to whether it changes management.','Do not infer benignity solely from absent pain or bleeding.'],[['Presentation','Often incidental'],['Triad','Not required'],['Assessment','Imaging and individualized plan']],[ref('NCI renal cell cancer professional summary','https://www.cancer.gov/types/kidney/hp/kidney-treatment-pdq')],style='clinical_scenario')

q('An older smoker taking anticoagulation develops painless visible hematuria. Which approach is appropriate?', 'Evaluate the urinary tract for malignancy and other causes rather than attributing bleeding to anticoagulation alone',[
 ('Anticoagulation makes cancer evaluation unnecessary','It can reveal bleeding from an underlying lesion.'),('Absence of pain excludes urothelial cancer','Painless hematuria is an important presentation.'),('A single negative urine culture excludes all serious causes','Culture addresses infection, not the entire differential.')],
 'A drug can expose a lesion without being the whole cause','**Urothelial malignancy is a key concern in this risk context.**',['Cystoscopy and upper-tract assessment are selected through the appropriate pathway.','Renal and other urological causes also need consideration.'],'**Assess bleeding severity and anticoagulation safely.**',['Do not stop essential treatment without an individualized plan.','Arrange timely evaluation even if bleeding settles.'],[['Risk','Age/smoking'],['Symptom','Visible hematuria'],['Drug','Does not remove malignancy concern']],[ref('NCI bladder cancer professional summary','https://www.cancer.gov/types/bladder/hp/bladder-treatment-pdq')],style='clinical_scenario')

q('A man with a prostate malignancy develops widespread osteoblastic skeletal lesions. Which interpretation is most appropriate?', 'The pattern is compatible with prostate-cancer metastases but still requires clinical and imaging correlation',[
 ('All skeletal metastases must be purely lytic','Bone response varies by tumor and can be mixed.'),('A high PSA alone measures the exact number of bone lesions','PSA does not map anatomical burden exactly.'),('Bone pain is required before metastatic disease can exist','Skeletal disease may initially be asymptomatic.')],
 'Tumor type influences the bone reaction','**Prostate metastases often have an osteoblastic appearance.**',['The pattern is supportive rather than uniquely diagnostic.','Assess fracture, cord compression and pain emergencies.'],'**Stage with appropriate contemporary imaging.**',['Review disease biology and prior treatment.','Do not infer the entire prognosis from one radiographic pattern.'],[['Prostate','Often osteoblastic'],['Exceptions','Mixed or other patterns possible'],['Urgent complications','Fracture/cord compression']],[ref('NCI prostate cancer professional summary','https://www.cancer.gov/types/prostate/hp/prostate-treatment-pdq')],style='clinical_scenario')

q('A testicular tumor reported as pure seminoma has a convincingly elevated AFP without another explanation. Which response is appropriate?', 'Reassess for a nonseminomatous component or another AFP source rather than accepting pure seminoma uncritically',[
 ('AFP elevation is expected in every pure seminoma','Pure seminoma does not produce AFP.'),('The AFP result proves the testicular lesion is benign','It raises a classification question rather than benignity.'),('Normal beta-hCG is required to exclude seminoma','Some seminomas can produce beta-hCG; that marker has a different interpretation.')],
 'Marker–pathology discordance can change classification','**AFP suggests yolk-sac or other nonseminomatous differentiation in this setting.**',['Liver disease and other sources need consideration.','Mixed germ-cell tumors can be missed in limited sampling.'],'**Review pathology, marker kinetics and staging with specialists.**',['Use the correct treatment-risk category.','Do not ignore a reliable discordant marker.'],[['Pure seminoma','AFP not produced'],['Elevated AFP','Reassess classification/source'],['Beta-hCG','Can rise in selected seminomas']],[TE],style='clinical_scenario')

q('Which serum-marker pattern is compatible with pure seminoma?', 'Normal AFP with possible beta-hCG elevation',[
 ('AFP elevation as a required feature','That suggests another component/source.'),('Every marker must be elevated','Markers may be normal.'),('A normal marker panel excludes all seminoma','Tissue and imaging establish the diagnosis.')],
 'Markers assist but do not replace diagnosis','**Seminoma and nonseminomatous tumors have different marker associations.**',['LDH can reflect burden but is nonspecific.','Interpret levels before and after treatment using expected kinetics.'],'**Use tumor type, extent and markers together.**',['Do not label a mass benign from normal markers.','Obtain appropriate testicular imaging and specialist care.'],[['AFP','Normal in pure seminoma'],['Beta-hCG','May be elevated'],['LDH','Nonspecific burden clue']],[TE])

q('A young man has a bulky midline retroperitoneal germ-cell tumor presentation but no reported testicular symptoms. Which assessment is important?', 'Examine and ultrasound the testes to assess for an occult or regressed primary',[
 ('No testicular symptoms prove an extragonadal primary','An occult primary can be clinically silent.'),('A retroperitoneal mass excludes germ-cell disease','This is a recognized metastatic distribution.'),('Biopsy and markers are unnecessary because of age alone','Age informs probability but does not establish histology.')],
 'The presenting mass may not be the primary site','**Testicular disease can present through metastatic symptoms.**',['Markers and pathology help classify the germ-cell process.','A burned-out primary can leave subtle findings.'],'**Complete appropriate testicular and systemic staging.**',['Coordinate prompt specialist management.','Do not use a normal self-reported examination as a substitute for imaging.'],[['Presentation','Retroperitoneal mass'],['Primary search','Testicular examination/ultrasound'],['Classification','Tissue and markers']],[TE],style='clinical_scenario')

q('A pigmented skin lesion is evolving, asymmetric and irregularly colored. Which diagnostic principle is appropriate?', 'Obtain a biopsy adequate to assess the full lesion depth, preferably complete excision with an appropriate narrow diagnostic margin when feasible',[
 ('Use destructive treatment before histology','This can remove essential diagnostic information.'),('Sample only the superficial pigment in every lesion','Depth assessment is important for melanoma staging.'),('Wait for bleeding or pain before evaluating','Early suspicious lesions may be asymptomatic.')],
 'The initial procedure must preserve staging information','**Melanoma assessment depends on invasive depth and other pathological features.**',['Technique is adapted to site and lesion size.','Other acceptable diagnostic approaches require adequate depth and expert judgment.'],'**Use a skin-cancer diagnostic pathway.**',['Do not perform an unplanned definitive wide excision before histological planning.','Assess regional nodes and risk after diagnosis.'],[['Clinical concern','Evolution/asymmetry'],['Biopsy goal','Diagnosis and depth'],['Technique','Adequate full-depth material']],[ME],style='clinical_scenario')

q('Which pathological measure is central to primary cutaneous melanoma staging?', 'Breslow thickness with relevant ulceration and nodal/metastatic information',[
 ('Surface diameter alone as a substitute for invasive depth','Diameter does not capture the same risk information.'),('Pigment darkness as a quantitative stage','Color is not a staging measure.'),('A positive family history as the sole T category','Family risk does not define primary tumor depth.')],
 'Invasion depth is more informative than surface appearance','**Breslow thickness measures vertical invasive extent in millimeters.**',['Ulceration and regional/distant spread add staging information.','The exact system and edition should be specified.'],'**Use the complete pathology report and appropriate nodal assessment.**',['Do not infer thickness from clinical darkness.','Plan margins and sentinel-node discussion using validated criteria.'],[['Primary measure','Breslow thickness'],['Additional feature','Ulceration'],['Overall stage','Nodes and distant spread']],[ME])
